// Targeting's answers.ts at console 9855e8c9,
// whole, so scripts/tests/targeting-selection.test.cjs
// replays table G against its `createAnswers`. answers.ts gathered b9b5c91e's attack controller
// `permitted` and the skill runtime's `authorized` and `allows` with their checks in b9b5c91e's order;
// at b9b5c91e they were closures of those factories, with no one answer to replay. Tables A, M and S
// replay b9b5c91e itself (fixtures/targeting-b9b5c91e.cjs).
exports.answers = "// The targeting owner's answers on the character (party-console-plan docs/specs/04-targeting-design.md\n// 3.2, 3.4, 5.3): `targeting.target`, `targeting.allows` and the porcupine's `change_target`. Each is\n// b9b5c91e's code with its checks in its order: the role runner's selection, the attack\n// controller's `permitted` and the skill runtime's `allows` (b9b5c91e runner.ts, attack-controller.ts,\n// skills/runtime.ts). The reads of the role runner, the skill runtime and the porcupine\n// swap come through the install port, as the turns executor reaches shared.js.\nimport { effectiveAttackDamageType, monsterAttackBlock, type ReflectLists } from './gates.ts';\nimport type { Target } from '../roles/types.ts';\nimport type { CallAnswer, CallQuestion } from '../../hooks/registry.ts';\nimport type { TargetingEntry } from './records.ts';\n\n// The answer of `targeting.target` (C36): the target, its passing flag, whether support casts may go\n// on it, and whether a selection is due (TGT-Q24 (a), E04-5). With no target the answer is `{ due:\n// true }` while a selection is due, and nothing otherwise.\nexport interface TargetAnswer { target: Target; passing: boolean; support: boolean; due: boolean }\n// The skill world the skill gate reads: the skill runtime's, the same one its engine judges with.\nexport interface GateWorld {\n  actor: { name: string; range: number };\n  skills: Readonly<Record<string, { damage_type?: string; hostile?: boolean } | undefined>>;\n}\nexport interface AnswerPorts {\n  hooks: {\n    targeting: { refuses(monster: unknown, skill: string): string | undefined };\n    calls: { band(question: CallQuestion): CallAnswer };\n  };\n  // The role runner's selection (runner.ts `attackTarget`, `currentTarget`, `passingTarget`).\n  attackTarget?(): Target | null;\n  currentTarget?(): Target | null;\n  passingTarget?(): Target | null;\n  // TGT-Q24 (a): a selection is due from the moment the target is lost until a selection finishes\n  // with no invalidation pending, and never while targeting is inactive or combat is not allowed.\n  // The role runner's `selecting` and `invalidated` answer it (ledger S-04d) until 04's V1.4 pass does.\n  due?(): boolean;\n  // The porcupine bow swap holds the attack while it changes weapons (TGT-011).\n  equipmentBusy?(): boolean;\n  // This character's two reflect lists (reflect.ts).\n  reflect(): ReflectLists;\n  // The skill runtime's world, and its scatter pull check (03's damage model, turns/skills/runtime.ts\n  // `pullSafe`), the last check of b9b5c91e's `authorized`.\n  world(): GateWorld | null;\n  // Franky's fight, an event fact (stand-in S88, stand-ins.ts).\n  franky(): boolean;\n  pullSafe(world: GateWorld, target: Target): boolean;\n  // The targeting ring (records.ts), which keeps each `allows` refusal (3.12).\n  record?(entry: TargetingEntry): void;\n}\n// Each refusal is one ring entry until it changes: the same reason on the same target for the same\n// skill writes nothing more, and an allow ends it (04-targeting-design 3.12, TG34).\nexport function refusalRecorder(record: (entry: TargetingEntry) => void) {\n  const last = new Map<string, string>();\n  return (target: { id?: unknown } | undefined, skill: string, reason: string | undefined): void => {\n    const key = reason ? `${String(target?.id)}|${reason}` : '';\n    if (!reason) { last.delete(skill); return; }\n    if (last.get(skill) === key) return;\n    last.set(skill, key);\n    record({ kind: 'refused', target: String(target?.id), skill, why: reason });\n  };\n}\n// The skills the return defence and Franky's boss-only fight refuse (b9b5c91e's sets in skills/runtime.ts).\nconst returnExcluded = new Set<string>(['taunt', 'agitate', 'charge', 'dash', 'blink', 'scare', 'stomp', 'cleave', 'fanofknives']);\nconst frankyExcluded = new Set<string>(['agitate', 'charge', 'dash', 'blink', 'scare', 'stomp', 'cleave', 'fanofknives']);\nconst hostile = (skill: string) => !!(G.skills as Record<string, { hostile?: boolean } | undefined>)[skill]?.hostile;\n\nexport function createAnswers(ports: AnswerPorts) {\n  const refused = refusalRecorder(entry => ports.record?.(entry));\n  const passing = (target: Target) => target.id !== ports.currentTarget?.()?.id && target.id === ports.passingTarget?.()?.id;\n  // The basic attack's gates (TGT-008 to TGT-010), the attack controller's `permitted` in b9b5c91e's\n  // order: eligibility, the weapon swap, disabled, the group's readiness, the reflect lists, the rare.\n  function attackGate(target: Target): string | undefined {\n    const eligible = passing(target) ? sharedRoutine.allowsPassingTarget(target) : sharedRoutine.allowsTarget(target);\n    if (!eligible) return \"target no longer eligible\";\n    if (ports.equipmentBusy?.()) return \"weapon equipment change in progress\";\n    const client = parent as unknown as { is_disabled?: (actor: typeof character) => boolean };\n    if (client.is_disabled?.(character)) return \"character disabled\";\n    if (!passing(target) && sharedRoutine.groupedAttackAllowed && !sharedRoutine.groupedAttackAllowed(target))\n      return \"waiting for group readiness and target commitment\";\n    const blocked = monsterAttackBlock(target.mtype, effectiveAttackDamageType(character, typeof G === \"undefined\" ? undefined : G), Number(character.range), ports.reflect());\n    if (blocked) return blocked;\n    if (sharedRoutine.rareAttackAllowed && !sharedRoutine.rareAttackAllowed(target, \"attack\")) return \"Fairy deployment or attack policy\";\n    return undefined;\n  }\n  function returnTargetBlocked(t: Target, id: string): boolean {\n    return !!sharedRoutine.returnCombatActive?.() && (returnExcluded.has(id) || !sharedRoutine.returnAttacker?.(t));\n  }\n  // Area effects and movement skills cannot honor strict boss-only, hold-position combat.\n  function frankySkillBlocked(id: string, targets: Target[]): boolean {\n    if (!ports.franky()) return false;\n    return frankyExcluded.has(id) || hostile(id) &&\n      targets.some(t => t.type !== 'monster' || t.mtype !== 'franky' || !sharedRoutine.skillTargetAllowed?.(t));\n  }\n  function targetAuthorized(t: Target, id: string): boolean {\n    return !!sharedRoutine.skillTargetAllowed?.(t) && sharedRoutine.rareAttackAllowed?.(t, id) !== false;\n  }\n  // Today's `authorized`: the return and Franky vetoes, the reflect lists by the skill's own damage\n  // type (Taunt excepted), the target gate, then the skill runtime's scatter pull check.\n  function authorized(w: GateWorld, t: Target, id: string): boolean {\n    if (returnTargetBlocked(t, id) || frankySkillBlocked(id, [t])) return false;\n    const type = w.skills[id]?.damage_type || 'physical';\n    if (id !== 'taunt' && monsterAttackBlock(t.mtype, type, w.actor.range, ports.reflect())) return false;\n    if (!targetAuthorized(t, id)) return false;\n    return ports.pullSafe(w, t);\n  }\n  // A skill's gates (TRN-010, TRN-020): the return and Franky vetoes on the skill, and for a hostile\n  // skill the target's.\n  function skillGate(t: Target | undefined, id: string): string | undefined {\n    if (sharedRoutine.returnCombatActive?.() && returnExcluded.has(id)) return 'Skill conflicts with return movement or attacker-only policy';\n    if (frankySkillBlocked(id, [])) return 'Skill conflicts with Franky-only combat';\n    if (!t || !hostile(id)) return undefined;\n    const w = ports.world();\n    return w && authorized(w, t, id) ? undefined : 'unauthorized or immune target';\n  }\n  return {\n    // The role runner's target, its passing flag, and the grouped readiness and tinyp gates on\n    // support casts (b9b5c91e runner.ts supportTick).\n    target(): TargetAnswer | { due: true } | undefined {\n      const target = ports.attackTarget?.(), due = !!ports.due?.();\n      if (!target) return due ? { due } : undefined;\n      const support = (!sharedRoutine.groupedAttackAllowed || sharedRoutine.groupedAttackAllowed(target)) &&\n        (target.mtype !== 'tinyp' || !!sharedRoutine.rareAttackAllowed?.(target, 'support'));\n      return { target, passing: passing(target), support, due };\n    },\n    // One answer for every hostile spend (C37): b9b5c91e's gates, then an add-on's refusal\n    // (`targeting.refuses`, TGT-Q9 (a)), which can only refuse.\n    allows(monster: unknown, skill: string): string | undefined {\n      const target = monster as Target | undefined;\n      const reason = (skill === 'attack' ? target ? attackGate(target) : undefined : skillGate(target, skill)) ??\n        (target ? ports.hooks.targeting.refuses(target, skill) : undefined);\n      refused(target, skill, reason);\n      return reason;\n    },\n    // TGT-020 (S69): melee classes keep a porcupine selected while the safety rule blocks attacks or\n    // the bow swap runs. The call asks the survival band first (09-call-budget-design 3.5).\n    changeTarget(target: Target): boolean {\n      if (typeof change_target !== 'function') return false;\n      if (ports.hooks.calls.band({ band: 'survival', method: 'target', data: { id: target.id } }) !== 'send') return false;\n      change_target(target);\n      return true;\n    },\n  };\n}\nexport type Answers = ReturnType<typeof createAnswers>;\n";
